    shown.findOne(n => n.name === 'Overline').componentPropertyReferences = { characters: set.addComponentProperty('Overline', 'TEXT', 'SEASON 1 · EPISODE 3'), visible: set.addComponentProperty('Show overline', 'BOOLEAN', true) };
