  await buildIcons();
  progress('Building the basic components…');
  await buildBasics();
  progress('Building dialogs…');
  await buildDialogs();
  progress('Building explorer pieces…');
  await buildExplorer();
  progress('Building pickers and feedback…');
  await buildPickers();
  progress('Building app and account pieces…');
  await buildApp();
  progress('Building media pieces…');
  await buildMedia();
  progress('Building layouts…');
  await buildLayouts();
  progress('Building music pieces…');
  await buildMusic();
  progress('Building suggestions, tooltips and transfers…');
  await buildSuggestAndTransfer();
  progress('Building what the screens need…');
  await buildMore();
  await buildSample();
