// A toolbar card (create, and the search at its end), then a card with the covers: the name and how much is
// in it, over the thumbnail as the app's captions are by default. A cover with a picture is a file tile, one
// without (nothing in it yet) a folder tile.
async function coverPage(page, o) {
  bindNum(page, 'itemSpacing', 'space/20');   // .sp-browse: the shell's gutter, 20 at this width
  const tools = await card(page, 'Commands card', 'space/16'); fill(tools);
  const row = auto('HORIZONTAL', 'Toolbar', 'space/8'); row.counterAxisAlignItems = 'CENTER'; tools.appendChild(row); fill(row);
  row.appendChild(use('Button', 'Style=Tonal, Size=sm', { Label: o.create, 'Show icon': true, Icon: 'Plus' }));
  const sp = spacer(); row.appendChild(sp); fill(sp);
  const search = use('SearchField', 'Filled=False', { Placeholder: o.search }); row.appendChild(search); search.resize(300, search.height);
  const covers = await card(page, 'Covers card', 'space/16'); fillBoth(covers);
  const grid = tileGrid('Covers'); covers.appendChild(grid); fillBoth(grid);
  for (const [name, count, pictured] of o.covers) {
    const t = use('MediaTile (overlay caption)', `Kind=${pictured ? 'File' : 'Folder'}, Drop target=False`, { Name: name, Meta: count }); t.name = name; grid.appendChild(t);
  }
}
