// ══ The folder picker (dialogs/FolderPickerDialog.tsx) ═══
// mode: tree (the list), tiles, search (a name typed, with its suggestions), or thumbs: a proposal, the
// tiles as square thumbnails with the folder's name inside, like the app's grid, in a wider dialog
async function picker(mode) {
  const thumbs = mode === 'thumbs', tiled = thumbs || mode === 'tiles';
  const m = auto('VERTICAL', 'Move to… dialog'); m.resize(thumbs ? 860 : 620, 100); m.counterAxisSizingMode = 'FIXED'; m.primaryAxisSizingMode = 'AUTO';
  if (!thumbs) bindNum(m, 'width', 'size/modal-max-width-wide');
  radius(m, 'radius/3xl'); m.fills = [await paint('surface/1')]; await elevate(m);
  const head = auto('HORIZONTAL', 'Header', 'space/12'); head.counterAxisAlignItems = 'CENTER'; pad(head, 'space/22', 'space/18', 'space/6', 'space/28'); m.appendChild(head); fill(head);
  const t = await text('Move IMG_0042.jpg to…', 'xl/Bold', 'text/1', 'Title'); head.appendChild(t); fill(t);
  head.appendChild(iconButton('Close', 'Close'));
  const body = auto('VERTICAL', 'Body', 'space/12'); pad(body, 'space/14', 'space/28', 'space/28', 'space/28'); m.appendChild(body); fill(body);

  // The search, and list / tiles
  const top = auto('HORIZONTAL', 'Search and view', 'space/6'); top.counterAxisAlignItems = 'CENTER'; body.appendChild(top); fill(top);
  const search = use('Combobox', `Variant=Search, Content=${mode === 'search' ? 'Filled' : 'Placeholder'}`, { Text: mode === 'search' ? 'summer' : 'Search folders' });
  top.appendChild(search); fill(search);
  top.appendChild(iconButton('ViewList', 'List', 'sm', tiled ? 'Default' : 'Active'));
  top.appendChild(iconButton('ViewTiles', 'Tiles', 'sm', tiled ? 'Active' : 'Default'));

  // The folders: 300 tall, on surface 2, scrolling (the thumbnails get 460, to show two rows and the start of a third)
  const box = auto('VERTICAL', 'Folders'); box.primaryAxisSizingMode = 'FIXED'; box.resize(thumbs ? 804 : 564, thumbs ? 460 : 300); box.clipsContent = true; radius(box, 'radius/lg');
  box.fills = [await paint('surface/2')]; body.appendChild(box); fill(box);
  let chosen = 'D:\\Projects\\Website';
  if (tiled) {
    pad(box, 'space/8', 'space/8', 'space/8', 'space/8'); bindNum(box, 'itemSpacing', 'space/6');
    // A thumbnail is the library's folder tile with its caption over it, at the grid's small size (150); the
    // one chosen wears the accent ring of a drop target, the nearest look the library has
    const tile = (name, meta, picked) => (thumbs
      ? tileAt(use('MediaTile (overlay caption)', `Kind=Folder, Drop target=${picked ? 'True' : 'False'}`, { Name: name, Meta: meta }), 150)
      : use('FileTile', null, { Name: name, Meta: meta }));
    const tiles = async (heading, list) => {
      if (heading) { const h = auto('HORIZONTAL', heading); pad(h, null, 'space/6', null, 'space/6'); h.appendChild(await caps(heading)); box.appendChild(h); }
      const row = auto('HORIZONTAL', `${heading || 'Here'} tiles`); row.layoutWrap = 'WRAP'; bindNum(row, 'itemSpacing', 'space/8'); bindNum(row, 'counterAxisSpacing', 'space/8'); box.appendChild(row); fill(row);
      for (const [name, meta, picked] of list) { const ft = tile(name, meta, picked); ft.name = name; row.appendChild(ft); }
    };
    await tiles('Recent', [['Summer Trip', 'D:\\Photos\\2026', thumbs], ['Projects', 'D:\\']]);
    await tiles('Quick access', [['Pictures', 'Folder'], ['Videos', 'Folder'], ['Music', 'Folder'], ['Clients', 'Pinned']]);
    const loc = auto('HORIZONTAL', 'Location', 'space/6'); loc.counterAxisAlignItems = 'CENTER'; box.appendChild(loc);
    loc.appendChild(iconButton('ArrowUp', 'Up one folder')); loc.appendChild(await text('D:\\Projects', 'sm/Medium', 'text/2', 'Path'));
    await tiles(null, [['Website', '12 folders'], ['Acme Photoshoot', '3 folders']]);
    chosen = thumbs ? 'D:\\Photos\\2026\\Summer Trip' : 'D:\\Projects';
  } else {
    pad(box, 'space/4', 'space/4', 'space/4', 'space/4');
    const add = (node, indent) => { if (indent) { const w = auto('VERTICAL', `${node.name} (inside)`); w.paddingLeft = 20; w.appendChild(node); box.appendChild(w); fill(w); fill(node); } else { box.appendChild(node); fill(node); } };
    const heading = label => { const h = use('TreeHeading', null, { Label: label }); h.name = label; return h; };
    add(heading('Recent'));
    add(treeRow('Summer Trip', 'Clock', 'Closed'));
    add(treeRow('Projects', 'Clock', 'Open'));
    add(treeRow('Website', 'Folder', 'Leaf', true), true);
    add(treeRow('Acme Photoshoot', 'Folder', 'Closed'), true);
    add(heading('Quick access'));
    for (const [label, ic] of [['Pictures', 'FolderSolid'], ['Videos', 'FolderSolid'], ['Music', 'FolderSolid'], ['Clients', 'Pin']]) add(treeRow(label, ic, 'Closed'));
    add(heading('This computer'));
    add(treeRow('Local Disk (C:)', 'Drive', 'Closed')); add(treeRow('Photos (D:)', 'Drive', 'Closed'));
  }

  // The folder: completes a path as it's typed; on the desktop a button opens Windows' own dialog
  const field = auto('VERTICAL', 'Folder field', 'space/6'); body.appendChild(field); fill(field);
  field.appendChild(await text('Folder', 'sm/SemiBold', 'text/2', 'Label'));
  const addr = use('Combobox', 'Variant=Field, Content=Filled', { Text: chosen, 'Show end button': true }); field.appendChild(addr); fill(addr);
  field.appendChild(await text('Pick a folder in the list, or type its path.', 'xs/Medium', 'text/3', 'Hint'));
  const acts = auto('HORIZONTAL', 'Actions', 'space/8'); acts.primaryAxisAlignItems = 'MAX'; body.appendChild(acts); fill(acts);
  acts.appendChild(use('Button', 'Style=Secondary, Size=md', { Label: 'Cancel' })); acts.appendChild(use('Button', 'Style=Primary, Size=md', { Label: 'Move here' }));

  // Typing a name in the search: folders found by name, by where they were found
  if (mode === 'search') {
    const list = find('ComboboxList').createInstance(); list.name = 'Suggestions';
    const opts = list.findAll(n => n.type === 'INSTANCE' && n.name === 'ComboboxOption');
    const groups = list.findAll(n => n.type === 'TEXT' && n.name === 'Group');
    const rows = [['Summer Trip', 'D:\\Photos\\2026\\Summer Trip', 'Clock'], ['Summer 2025', 'D:\\Photos\\2025\\Summer 2025', 'FolderSolid'], ['Summer edits', 'E:\\Work\\Summer edits', 'Folder']];
    opts.forEach((o, i) => { if (rows[i]) { prop(o, 'Label', rows[i][0]); prop(o, 'Detail', rows[i][1]); prop(o, 'Icon', icon(rows[i][2]).id); } });
    if (groups[1]) groups[1].characters = 'IN YOUR LIBRARY';
    return { dialog: m, list };
  }
  return { dialog: m };
}

// ══ The media viewer, as the app shows it ════════════════
// The design system's MediaViewer with ViewerHost's tools and InspectorContent in its panel
// (src/ui/viewer/ViewerHost.tsx, src/ui/inspector/InspectorContent.tsx, app.css .sp-inspector*): a card over
